<?php
namespace App\Http\Resources; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\JsonResource;
class ControllerResource extends JsonResource {public function toArray(Request $r):array{return ['id'=>$this->id,'machine_id'=>$this->machine_id,'controller_code'=>$this->controller_code,'controller_name'=>$this->name,'model'=>$this->model_type,'slave_id'=>$this->slave_id,'communication'=>$this->communication,'baudrate'=>$this->baudrate,'parity'=>$this->parity,'stop_bit'=>$this->stopbits,'polling_interval'=>$this->polling_interval,'firmware_version'=>$this->firmware_version,'status'=>$this->status,'machine'=>new MachineResource($this->whenLoaded('machine')),'devices'=>DeviceResource::collection($this->whenLoaded('devices')),'created_at'=>$this->created_at,'updated_at'=>$this->updated_at];}}
